package dev.winnie.app.ui

import android.content.Context
import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Rect
import androidx.core.content.ContextCompat
import androidx.test.core.app.ApplicationProvider
import dev.winnie.app.R
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.GraphicsMode

/**
 * Renders the real launcher resources.
 *
 * The icons are generated by `tools/brand/build.py`, and a malformed vector
 * fails silently: the build stays green and the launcher falls back to a
 * default icon. These assertions pin the two things that make the icon
 * recognisable — the paper disc on the navy field, and the themed layer
 * carrying the bird without the frame — so a regeneration with the wrong
 * radius or a broken clip fails here instead of on a home screen.
 *
 * There is no emulator on the build machine, so this is the only place the
 * compiled drawables are actually rasterised.
 */
@RunWith(RobolectricTestRunner::class)
@GraphicsMode(GraphicsMode.Mode.NATIVE)
class LauncherIconTest {

    private val context: Context = ApplicationProvider.getApplicationContext()

    /** The adaptive icon draws its 108 dp art at 1.5x, showing the middle 72 dp. */
    private fun render(resource: Int, size: Int = 162): Bitmap {
        val drawable = requireNotNull(ContextCompat.getDrawable(context, resource))
        val bitmap = Bitmap.createBitmap(size, size, Bitmap.Config.ARGB_8888)
        drawable.setBounds(0, 0, size, size)
        drawable.draw(Canvas(bitmap))
        return bitmap
    }

    private fun opaqueBounds(bitmap: Bitmap): Rect {
        var left = bitmap.width
        var top = bitmap.height
        var right = -1
        var bottom = -1
        for (y in 0 until bitmap.height) {
            for (x in 0 until bitmap.width) {
                if (Color.alpha(bitmap.getPixel(x, y)) > 128) {
                    left = minOf(left, x)
                    top = minOf(top, y)
                    right = maxOf(right, x)
                    bottom = maxOf(bottom, y)
                }
            }
        }
        return if (right < 0) Rect() else Rect(left, top, right, bottom)
    }

    private fun count(bitmap: Bitmap, predicate: (Int) -> Boolean): Int {
        var total = 0
        for (y in 0 until bitmap.height) {
            for (x in 0 until bitmap.width) {
                if (predicate(bitmap.getPixel(x, y))) total++
            }
        }
        return total
    }

    @Test
    fun adaptiveIconDrawsPaperDiscOnNavyField() {
        val icon = render(R.mipmap.ic_launcher)
        val ink = Color.rgb(0x00, 0x30, 0x87)

        assertEquals("the mark is inked at the centre", ink, icon.getPixel(81, 81))
        assertEquals("the field reaches the mask edge", ink, icon.getPixel(81, 3))
        assertEquals(
            "the launcher mask crops the corners",
            0,
            Color.alpha(icon.getPixel(0, 0)),
        )

        val paper = count(icon) { it == Color.WHITE }
        assertTrue("the paper disc is drawn ($paper px)", paper > 8_000)
    }

    @Test
    fun monochromeLayerCarriesTheBirdWithoutTheFrame() {
        val glyph = render(R.drawable.ic_launcher_monochrome)

        val bounds = opaqueBounds(glyph)
        assertTrue("the bird is drawn ($bounds)", !bounds.isEmpty)
        assertEquals(
            "the bird is centred horizontally",
            81.0,
            (bounds.left + bounds.right) / 2.0,
            1.5,
        )
        assertEquals(
            "the bird is centred vertically",
            81.0,
            (bounds.top + bounds.bottom) / 2.0,
            1.5,
        )

        // The frame circle would pass through this point; the clip removes it,
        // because a themed icon gets its container from the system.
        assertEquals(
            "the frame is clipped away",
            0,
            Color.alpha(glyph.getPixel(82, 23)),
        )
    }
}
